NORMALIZED_SCHEMAS_HEADER_MAGIC_OFFSET = 0
NORMALIZED_SCHEMAS_HEADER_MAGIC_END = 8
NORMALIZED_SCHEMAS_HEADER_FORMAT_VERSION_OFFSET = 8
NORMALIZED_SCHEMAS_HEADER_FORMAT_VERSION_END = 12
NORMALIZED_SCHEMAS_HEADER_HEADER_SIZE_OFFSET = 12
NORMALIZED_SCHEMAS_HEADER_HEADER_SIZE_END = 16
NORMALIZED_SCHEMAS_HEADER_REQUIRED_FLAGS_OFFSET = 16
NORMALIZED_SCHEMAS_HEADER_REQUIRED_FLAGS_END = 24
NORMALIZED_SCHEMAS_HEADER_SCHEMA_COUNT_OFFSET = 24
NORMALIZED_SCHEMAS_HEADER_SCHEMA_COUNT_END = 28
NORMALIZED_SCHEMAS_HEADER_TOTAL_LEN_OFFSET = 28
NORMALIZED_SCHEMAS_HEADER_TOTAL_LEN_END = 32

NORMALIZED_SCHEMAS_ENTRY = struct.Struct("<32sII")
NORMALIZED_SCHEMAS_ENTRY_IDENTITY_OFFSET = 0
NORMALIZED_SCHEMAS_ENTRY_IDENTITY_END = 32
NORMALIZED_SCHEMAS_ENTRY_NORMALIZED_LEN_OFFSET = 32
NORMALIZED_SCHEMAS_ENTRY_NORMALIZED_LEN_END = 36
NORMALIZED_SCHEMAS_ENTRY_RESERVED_OFFSET = 36
NORMALIZED_SCHEMAS_ENTRY_RESERVED_END = 40

def sha256(data: bytes) -> bytes:
    return hashlib.sha256(data).digest()


def generation_identity(data: bytes) -> bytes:
    return sha256(
        data[:GENERATION_HEADER_IDENTITY_OFFSET]
        + bytes(GENERATION_HEADER_IDENTITY_END - GENERATION_HEADER_IDENTITY_OFFSET)
        + data[GENERATION_HEADER_IDENTITY_END:]
    )


def bootstate_checksum(slot: bytes) -> bytes:
    return sha256(
        slot[:BOOTSTATE_CHECKSUM_OFFSET]
        + bytes(BOOTSTATE_CHECKSUM_END - BOOTSTATE_CHECKSUM_OFFSET)
        + slot[BOOTSTATE_CHECKSUM_END:]
    )


def bootstore_checksum(data: bytes) -> bytes:
    offset = BOOTSTORE_DIRECTORY_OFFSET + BOOTSTORE_HEADER_CHECKSUM_OFFSET
    end = BOOTSTORE_DIRECTORY_OFFSET + BOOTSTORE_HEADER_CHECKSUM_END
    return sha256(data[BOOTSTATE_SLOT_BYTES * BOOTSTATE_SLOT_COUNT : offset] + bytes(end - offset) + data[end:])
